insert='''\n    private fun showReceiverCenter(events: List<AttendanceEvent>) {\n        val receivers = repo.authorizedReportReceivers()\n        val labels = mutableListOf(t("＋ ربط هاتف استلام جديد", "＋ Link new receiver phone"))\n        labels.addAll(receivers.map { "${if (it.active) "●" else "○"} ${it.name} • ${if (it.active) t("مصرح", "Authorized") else t("موقوف", "Disabled")}" })\n        AlertDialog.Builder(this).setTitle(t("هواتف استلام التقارير", "Report receiver phones"))\n            .setMessage(t("لربط هاتف جديد: افتح «استلام التقارير» في الهاتف الثاني واضغط «عرض QR تعريف هذا الهاتف»، ثم اختر «ربط هاتف استلام جديد» هنا وامسح الرمز. بعد القبول سيظهر QR الربط الثاني لهذا الهاتف.", "On the receiver phone open Report Receiving and show its identification QR. Then choose Link new receiver phone here and scan it. After approval, the second linking QR will be shown for that phone."))\n            .setItems(labels.toTypedArray()) { _, which ->\n                if (which == 0) {\n                    startActivityForResult(Intent(this, QrScannerActivity::class.java).putExtra(QrScannerActivity.EXTRA_PROMPT, t("امسح QR تعريف هاتف الاستلام", "Scan receiver identification QR")), REQUEST_REPORT_RECEIVER_QR)\n                } else {\n                    val r = receivers[which-1]\n                    val actions = arrayOf(t("إرسال التقرير الآن", "Send report now"), if (r.active) t("إيقاف الهاتف", "Disable phone") else t("تفعيل الهاتف", "Enable phone"), t("حذف الهاتف", "Remove phone"))\n                    AlertDialog.Builder(this).setTitle(r.name).setItems(actions) { _, a ->\n                        when(a) {\n                            0 -> if (r.active) shareToReceiver(events, r) else info(t("الهاتف موقوف", "Phone disabled"), t("فعّل الهاتف أولًا.", "Enable the phone first."))\n                            1 -> { repo.setReportReceiverActive(r.receiverId, !r.active); buildUi() }\n                            2 -> { repo.removeReportReceiver(r.receiverId); buildUi() }\n                        }\n                    }.show()\n                }\n            }.setNegativeButton(t("إغلاق", "Close"), null).show()\n    }\n\n    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {\n        super.onActivityResult(requestCode, resultCode, data)\n        if (requestCode != REQUEST_REPORT_RECEIVER_QR || resultCode != RESULT_OK) return\n        val raw = data?.getStringExtra(QrScannerActivity.EXTRA_RESULT).orEmpty()\n        val invite = ReportProtocol.decodeInvite(raw)\n        if (invite == null) { info(t("QR غير صالح", "Invalid QR"), t("اعرض QR تعريف هذا الهاتف من شاشة استلام التقارير في الهاتف الثاني ثم امسحه هنا.", "Show this phone identification QR on the receiver phone, then scan it here.")); return }\n        repo.authorizeReportReceiver(invite)\n        if (repo.isCentralActivationActive() && repo.serverUrl.isNotBlank()) {\n            Thread {\n                val result = CentralServerClient.registerReceiver(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(this), invite.receiverId, invite.name, invite.secret)\n                runOnUiThread {\n                    if (result.isSuccess) {\n                        val grant = ReportProtocol.RemoteReceiverGrant(invite.receiverId, repo.serverUrl, repo.storeName, repo.branchId, System.currentTimeMillis()+10*60_000L)\n                        val encoded = ReportProtocol.encodeRemoteGrant(grant)\n                        val bmp = runCatching { com.attendpro.core.QrCodeTools.bitmap(encoded, 700) }.getOrNull()\n                        if (bmp != null) {\n                            val image = android.widget.ImageView(this).apply { setImageBitmap(bmp); adjustViewBounds=true }\n                            AlertDialog.Builder(this).setTitle(t("تم قبول الهاتف ✓ — امسح QR الربط", "Phone accepted ✓ — scan linking QR"))\n                                .setMessage(t("الآن في هاتف الاستلام اضغط «مسح QR الربط من جهاز المحل» وامسح هذا الرمز. صالح لمدة 10 دقائق.", "On the receiver phone tap Scan linking QR from Store device and scan this code. Valid for 10 minutes."))\n                                .setView(image).setPositiveButton(t("تم", "Done"), null).show()\n                        } else info(t("تم قبول الهاتف", "Phone accepted"), t("تعذر رسم QR الربط. أعد فتح مركز هواتف الاستلام.", "Unable to render linking QR. Reopen receiver center."))\n                    } else info(t("تمت الإضافة محليًا", "Added locally"), t("تعذر تسجيل الهاتف في الخادم الآن. تحقق من الإنترنت ثم أعد الربط.", "Server registration is unavailable. Check Internet and link again."))\n                    buildUi()\n                }\n            }.start()\n        } else info(t("تمت إضافة الهاتف", "Phone added"), t("تم حفظ الهاتف محليًا. ربط الاستلام عبر الإنترنت يحتاج الخادم المركزي.", "Phone saved locally. Online receiving requires the central server."))\n    }\n'''
